DROP TABLE IF EXISTS `products_variants`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products_variants` (
  `variant_product_id` int NOT NULL AUTO_INCREMENT,
  `product_id` int DEFAULT NULL,
  `sku` varchar(20) NOT NULL,
  `color` varchar(20) DEFAULT NULL,
  `size` varchar(5) DEFAULT NULL,
  `price` decimal(5,2) DEFAULT NULL,
  `stock_quantity` int NOT NULL,
  `active` varchar(7) NOT NULL,
  PRIMARY KEY (`variant_product_id`),
  UNIQUE KEY `sku` (`sku`),
  KEY `product_id` (`product_id`),
  CONSTRAINT `products_variants_ibfk_1` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`) ON DELETE SET NULL,
  CONSTRAINT `products_variants_chk_1` CHECK ((`price` >= 0)),
  CONSTRAINT `products_variants_chk_2` CHECK ((`stock_quantity` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=1284 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

