INSERT INTO `faq` VALUES (1,'How long does delivery take?','Standard delivery usually takes 2 to 5 business days.'),(2,'Can I cancel my order?','Orders can be cancelled before they are shipped.'),(3,'What is your return policy?','Products can be returned within 14 days of delivery if they meet the return conditions.'),(4,'Which payment methods do you accept?','We accept credit cards, debit cards, and supported digital payment methods.'),(5,'How can I track my order?','You can track your order using the tracking number provided after your order has been shipped.'),(6,'Can I change my shipping address after placing an order?','The shipping address can only be changed before the order has been shipped.'),(7,'What should I do if my order arrives damaged?','Contact customer support and provide details about the damaged product so the issue can be reviewed.'),(8,'Do you offer international shipping?','International shipping is available only for supported countries and regions.'),(9,'How long does it take to receive a refund?','Approved refunds are usually processed within 5 to 10 business days.'),(10,'Can I exchange a product instead of returning it?','Eligible products can be exchanged according to the store\'s exchange conditions and product availability.');
/*!40000 ALTER TABLE `faq` ENABLE KEYS */;
